// Normaliza a saída do AI Agent para o formato { reply } que o site espera.
// Também corta o tamanho e evita resposta vazia quebrando o front-end.

const out = $input.first().json;

let reply = (out.output || out.text || '').toString().trim();

if (!reply) {
  reply = 'Não consegui gerar uma resposta agora. Tente reformular a pergunta ou fale direto com o Marcos pelo WhatsApp (98) 98480-8565.';
}

return [{ json: { reply: reply.slice(0, 4000) } }];
